use std::sync::Mutex;

fn main() {
    let counter = Mutex::new(0);
    {
        let mut guard = counter.lock().unwrap();
        *guard += 1;
    }   // the guard is dropped here, so the lock is released
    println!("counter = {}", *counter.lock().unwrap());
}

// Output:
// counter = 1

use std::rc::Rc;
use std::sync::Mutex;
use std::thread;

// This does NOT compile: error[E0277]: `Rc<Mutex<i32>>` cannot be sent
// between threads safely.
fn broken() {
    let counter = Rc::new(Mutex::new(0));
    let handle = thread::spawn(move || {
        *counter.lock().unwrap() += 1;
    });
    handle.join().unwrap();
}

use std::sync::{Arc, Mutex};
use std::thread;

fn main() {
    let counter = Arc::new(Mutex::new(0));
    let mut handles = Vec::new();
    for _ in 0..8 {
        let counter = Arc::clone(&counter);   // each thread owns one Arc
        let handle = thread::spawn(move || {
            for _ in 0..1000 {
                *counter.lock().unwrap() += 1;   // the guard is dropped at the end of this line
            }
        });
        handles.push(handle);
    }
    for handle in handles {
        handle.join().unwrap();
    }
    println!("total = {}", *counter.lock().unwrap());
}

// Output:
// total = 8000

use std::sync::Mutex;

// Do not run this: the second lock never succeeds (it hangs, or may panic).
fn deadlock(m: &Mutex<i32>) {
    let first = m.lock().unwrap();
    let second = m.lock().unwrap();   // waits for `first`, which is only dropped at the end
    println!("{first} {second}");
}

